'use strict';

const assert=require('node:assert/strict');
const http=require('node:http');
const {createHash}=require('node:crypto');
const {partitionScoSelectedAsyncExports,bindScoModuleExports,createScoHandler}=require('../src');
const {cloneInHashBasis}=require('./rankthree-random-basis-attack');

const TOKEN='authenticated-rankthree-negative-study';
const SEED=0x9f135c21;

/** A request generated by the offline-interpolation learner. */
class NeedOracleValue extends Error {
  /** @param {number} input */
  constructor(input){
    super('Need another authorized oracle response');
    this.input=input>>>0;
  }
}

/**
 * Query only the public SCO endpoint with one legitimate credential.
 * @param {{origin:string,method:string,credential:string}} access
 * @param {number} input
 * @returns {Promise<number>}
 */
async function query(access,input){
  const response=await fetch(access.origin+'/obfs/rpc',{
    method:'POST',
    headers:{'content-type':'application/json','x-demo-session':access.credential},
    body:JSON.stringify({method:access.method,args:[input>>>0]})
  });
  assert.equal(response.status,200,'Legitimate SCO oracle input was denied');
  /** @type {{ok?:boolean,value?:unknown}} */
  const parsed=await response.json();
  assert.equal(parsed.ok,true);
  assert.ok(typeof parsed.value==='number'&&Number.isInteger(parsed.value)&&
    parsed.value>=0&&parsed.value<2**32);
  return parsed.value;
}

/**
 * The synchronous mathematical learner is replayed only from already observed
 * public responses. Missing values cause one real asynchronous HTTP query;
 * the resulting cache makes each requested input cost exactly one RPC.
 *
 * @param {{origin:string,method:string,credential:string}} access
 * @returns {Promise<{evaluate:(x:number)=>number,queryCount:number,
 *   pivots:number,early:boolean,observed:Set<number>,transcriptSha256:string}>}
 */
async function learn(access){
  /** @type {Map<number,number>} */
  const values=new Map();
  const transcript=createHash('sha256');
  while(true){
    try{
      const model=cloneInHashBasis(x=>{
        const input=x>>>0;
        if(!values.has(input))throw new NeedOracleValue(input);
        return /** @type {number} */ (values.get(input));
      },32,3,SEED);
      assert.equal(values.size,model.queries);
      return {
        evaluate:model.evaluate,queryCount:values.size,
        pivots:model.pivots,early:model.early,observed:new Set(values.keys()),
        transcriptSha256:transcript.digest('hex')
      };
    }catch(error){
      if(!(error instanceof NeedOracleValue))throw error;
      assert.equal(values.has(error.input),false);
      const value=await query(access,error.input);
      values.set(error.input,value);
      transcript.update(JSON.stringify([error.input,value])+'\n');
    }
  }
}

/**
 * A genuine server-private SCO quadratic with input nonlinear rank 3.
 * Public source contains only an async facade. A credentialed attacker learns
 * its complete 32-bit input/output behavior, then verifies independently
 * against a private evaluator after the original HTTP server is shut down.
 *
 * @returns {Promise<{queries:number,privateExecutions:number,heldouts:number,
 *   matched:number,pivots:number,early:boolean,deniedStatus:number,
 *   publishedBytes:number,privateSourceBytes:number,
 *   publicSecretLeaked:boolean,offlineAfterClose:boolean,
 *   sourceSha256:string,transcriptSha256:string}>}
 */
async function main(){
  const source=[
    'const OBFS_SECRET_OFFSET=0x5f3759df;',
    'const OBFS_SECRET_C01=0x89abcdef;',
    'const OBFS_SECRET_C02=0x13579bdf;',
    'const OBFS_SECRET_C12=0x2468ace0;',
    'export async function protectedRank3(value){',
    '  const x=value>>>0;',
    '  const a=(x>>>29)&1,b=(x>>>30)&1,c=(x>>>31)&1;',
    '  const linear=(x^(x>>>11)^(x<<7))>>>0;',
    '  return (linear^OBFS_SECRET_OFFSET^',
    '    ((a&b)?OBFS_SECRET_C01:0)^',
    '    ((a&c)?OBFS_SECRET_C02:0)^',
    '    ((b&c)?OBFS_SECRET_C12:0))>>>0;',
    '}',
    'export function publicIdentity(value){return value>>>0;}'
  ].join('\n');
  const selected=partitionScoSelectedAsyncExports({
    path:'mixed.mjs',sourceType:'module',code:source
  },{seed:'sco-rankthree-basis-negative',privateNames:['protectedRank3']});
  const publicCode=selected.clientFile.code;
  const publicSecretLeaked=/OBFS_SECRET_/u.test(publicCode);
  assert.equal(publicSecretLeaked,false);
  const privateModule=await import('data:text/javascript,'+encodeURIComponent(source));
  const bound=bindScoModuleExports(selected,privateModule);
  let privateExecutions=0;
  /** @type {Record<string,(...args:any[])=>unknown|Promise<unknown>>} */
  const methods=Object.create(null);
  for(const [name,fn] of Object.entries(bound)){
    methods[name]=(...args)=>{
      privateExecutions++;
      return fn(...args);
    };
  }
  let server=/** @type {import('node:http').Server|undefined} */ (undefined);
  try{
    const instance=http.createServer(createScoHandler([selected.clientFile],{
      remoteMethods:methods,
      authorizeRead:req=>req.headers['x-demo-session']===TOKEN,
      authorizeRpc:req=>req.headers['x-demo-session']===TOKEN,
      authorizeOperation:(req,method,args)=>
        req.headers['x-demo-session']===TOKEN&&
        method===selected.methodNames.protectedRank3&&args.length===1&&
        Number.isInteger(args[0])&&
        /** @type {number} */ (args[0])>=0&&
        /** @type {number} */ (args[0])<2**32
    }));
    server=instance;
    /** @type {Promise<void>} */
    const ready=new Promise((resolve,reject)=>{
      instance.once('error',reject);
      instance.listen(0,'127.0.0.1',()=>resolve());
    });
    await ready;
    const addr=instance.address();
    assert.ok(addr&&typeof addr!=='string');
    const origin='http://127.0.0.1:'+addr.port;
    const denied=await fetch(origin+'/obfs/rpc',{
      method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({method:selected.methodNames.protectedRank3,args:[7]})
    });
    assert.equal(denied.status,403);
    const publicResponse=await fetch(origin+'/obfs/mixed.mjs',{
      headers:{'x-demo-session':TOKEN}
    });
    assert.equal(publicResponse.status,200);
    const actuallyServed=await publicResponse.text();
    assert.equal(actuallyServed,publicCode);
    const match=actuallyServed.match(
      /export async function protectedRank3\([^)]*\)\{return await [\w$]+\("([^"]+)",\[\.\.\.arguments\]\);\}/u);
    assert.ok(match?.[1],'Public facade method route not recoverable');
    const learned=await learn({origin,method:match[1],credential:TOKEN});
    assert.ok(learned.early&&learned.queries<=529);
    assert.equal(privateExecutions,learned.queryCount);
    const closing=instance;
    /** @type {Promise<void>} */
    const closed=new Promise((resolve,reject)=>closing.close(error=>error?reject(error):resolve()));
    await closed;
    server=undefined;

    let matched=0,heldouts=0;
    for(let i=0;heldouts<1028;i++){
      const digest=createHash('sha256').update('heldout-rankthree-'+i).digest();
      const input=digest.readUInt32BE(0);
      if(learned.observed.has(input))continue;
      if(learned.evaluate(input)===await privateModule.protectedRank3(input))matched++;
      heldouts++;
    }
    assert.equal(matched,heldouts);
    assert.equal(privateExecutions,learned.queryCount,'Offline clone made a private RPC');
    const result={
      queries:learned.queryCount,privateExecutions,
      heldouts,matched,pivots:learned.pivots,early:learned.early,
      deniedStatus:denied.status,publishedBytes:Buffer.byteLength(publicCode),
      privateSourceBytes:Buffer.byteLength(source),
      publicSecretLeaked,offlineAfterClose:true,
      sourceSha256:createHash('sha256').update(source).digest('hex'),
      transcriptSha256:learned.transcriptSha256
    };
    console.log('SCO_RANKTHREE_RANDOM_BASIS_LIVE '+JSON.stringify(result));
    return result;
  }finally{
    if(server){
      const closing=server;
      /** @type {Promise<void>} */
      const closed=new Promise((resolve,reject)=>closing.close(error=>error?reject(error):resolve()));
      await closed;
    }
  }
}

if(require.main===module)main().catch(error=>{console.error(error);process.exitCode=1;});
module.exports={main,learn};
